package main

import (
    "context"
    "fmt"
    "log"
    "time"

    gridapi "github.com/bugylabs/gridapi-sdk/packages/go"
)

func main() {
    client, err := gridapi.NewClient() // reads GRIDAPI_API_KEY
    if err != nil {
        log.Fatal(err)
    }

    ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
    defer cancel()

    res, err := client.Get(ctx, "acme", "users", &gridapi.QueryOptions{Limit: 10, Page: 1})
    if err != nil {
        log.Fatal(err)
    }
    for _, row := range res.Data {
        fmt.Println(row["id"], row["name"])
    }
    fmt.Println("total:", res.Meta.Total)
}

use gridapi_sdk::{Client, GridRecord, QueryOptions};

fn main() -> Result<(), gridapi_sdk::GridError> {
    // Reads GRIDAPI_API_KEY, GRIDAPI_BASE_URL, GRIDAPI_TIMEOUT_MS from the env.
    let client = Client::from_env()?;

    let options = QueryOptions {
        filter: Some("status:active".into()),
        limit: Some(10),
        ..Default::default()
    };
    let page = client.get("acme", "users", &options)?;
    println!("{} of {} rows", page.data.len(), page.meta.total);

    let mut row = GridRecord::new();
    row.insert("name".into(), Some("Ann".into()));
    row.insert("email".into(), Some("ann@example.com".into()));
    let created = client.post("acme", "users", &[row])?;
    println!("inserted {} record(s)", created.inserted);

    Ok(())
}
